"""Explain RCU reference slowpaths and final-release races."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1397': ('사용 종료 표지와 너무 커져 셀 수 없는 장부 표지는 다릅니다. 종료된 물건은 새 사용을 거절하고, 셈이 넘친 물건은 실수로 버리지 않도록 남겨 둡니다.', 'rcuref의 종료 구역과 포화 구역에서 다른 결과를 내는 이유를 이해합니다.', '관측 값 0xe0000001은 DEAD로 복구·실패, 0xa0000001은 SATURATED로 복구·성공이라고 적으세요. 성공이라고 정확한 참조 수를 센 것은 아니라는 메모도 붙이세요.', ['rcuref_get은 먼저 내부 수를 올립니다. 결과가 음수로 보이면 rcuref_get_slowpath라는 별도 처리로 넘어옵니다. 여기서는 수를 unsigned로 다시 읽어 어느 상태 구역인지 판단합니다. 앞선 계산 뒤 다른 작업이 상태를 바꿨을 수도 있습니다.', '새로 읽은 cnt가 RELEASED=0xc0000000 이상이면 종료 구역입니다. 내부 값을 DEAD=0xe0000000으로 되돌리고 false를 반환합니다. 앞선 증가 때문에 DEAD+1이 되었더라도 새 참조를 주지 않는 것입니다.', '종료 구역이 아니지만 MAXREF=0x7fffffff보다 크면 포화 구역입니다. 너무 큰 수를 정확하게 계속 세기 어려운 상태입니다. 경고 조건을 확인하고 SATURATED=0xa0000000이라는 구역 가운데 표시로 되돌립니다.', '포화에서는 true를 반환합니다. 숫자를 계속 올려 작은 값으로 돌아가면 아직 사용하는 사람이 있는데도 없는 것으로 오해할 수 있습니다. 그래서 정확한 수 계산과 정상 반납을 포기하고 객체를 남겨 두어 그런 손상을 막습니다. 메모리 누수를 감수하는 보호 선택입니다.', '이미 포화된 값의 get도 포화 표시로 복구합니다. 반환 true를 정상 참조 수가 무한히 정확하게 늘어난다는 뜻으로 읽으면 안 됩니다. 포화 상태의 put도 객체 파괴를 허용하지 않는 규칙과 연결됩니다.', '경쟁 때문에 다시 읽은 값이 일반 구역이면 두 조건을 지나 true를 반환하고 그대로 둡니다. 따라서 별도 처리에 왔다는 사실만으로 종료 상태나 실패라고 단정하면 안 됩니다. 최종 관측 구역과 반환을 함께 확인하세요.'], [('종료 구역을 관측한 get slowpath는 어떻게 처리할까요?', ['SATURATED로 바꾸고 true를 반환해요', 'DEAD로 되돌리고 false를 반환해요'], '종료 구역은 이미 새 참조를 거절해야 하는 상태입니다. 포화 상태와 달리 실패를 돌려주며 증가로 흔들린 표시를 DEAD로 복구합니다.'), ('포화 구역에서 false를 돌려 즉시 반납하게 할까요?', ['아니요. true를 돌려주며 객체 파괴를 막는 포화 상태를 유지해요', '네. 음수 결과는 모두 즉시 반납하라는 뜻이에요'], '포화와 종료는 다른 상태입니다. 포화는 잘못된 작은 수로 돌아가 일찍 해제되는 것을 막기 위해 메모리를 남기는 선택이며, true가 정상적인 정확한 개수 측정을 뜻하지는 않습니다.')]), 'os1398': ('사용 약속 하나를 반납했다고 물건을 버려도 되는 것은 아닙니다. 다른 사용자가 남았는지, 마지막 확인을 누가 끝냈는지 알아야 합니다.', 'put의 감소와 최종 파괴 허가를 구별하고 호출 문맥을 이해합니다.', '실제 참조 둘은 내부 1입니다. 하나를 놓으면 내부 0이 되어 실제 하나가 남고 반환은 false입니다. 내부 0에서 놓는 경우는 NOREF가 되어 별도 처리가 필요하다고 적으세요.', ['__rcuref_put은 내부용 함수입니다. 헤더는 직접 호출하지 말라고 적고 있습니다. 외부에서는 일반 rcuref_put 또는 이미 안전한 문맥이라는 조건에 맞는 rcuref_put_rcusafe를 사용합니다.', '문맥은 지금 코드가 어떤 실행 조건 안에 있는지 뜻합니다. RCU 읽기 보호가 있는지, 다른 작업으로 실행이 바뀔 수 있는지 등이 포함됩니다. RCU는 읽는 쪽이 남아 있을 수 있는 동안 메모리 반납을 미루는 규칙을 제공합니다.', '시작의 RCU_LOCKDEP_WARN은 RCU 읽기 보호도 없고 선점 가능한 상황을 의심 조건으로 표시합니다. 진단이 있다고 자동으로 안전한 문맥을 만들어 주는 것은 아닙니다. 일반 wrapper는 선점을 금지하고 helper를 호출한 뒤 되돌립니다.', '본체는 atomic_add_negative_release(-1)로 먼저 하나 줄입니다. release는 그 전에 수행한 데이터 접근과 이 감소의 순서를 맞추는 약속입니다. 내부 값은 실제 참조 수보다 하나 작다는 점도 함께 기억하세요.', '새 값이 음수가 아니면 아직 일반 구역이므로 false를 반환합니다. 예를 들어 내부 1에서 0이 되면 실제 참조는 둘에서 하나로 줄었습니다. 감소는 일어났지만 마지막 처리를 허가하는 것은 아닙니다.', '새 값이 음수이면 slowpath가 마지막 참조, 포화, 종료 구역을 구별합니다. false는 객체를 파괴해도 된다는 뜻이 아닙니다. 마지막 성공에서 필요한 추가 순서 보장과 참조 경쟁 판단은 별도 처리에 있으며, 이 helper의 감소만 보고 임의로 free하면 안 됩니다.'], [('일반 구역에 남은 put이 false를 반환하면 객체를 반납해도 될까요?', ['네. 마지막 참조 해제 성공이라는 뜻이에요', '아니요. 파괴 허가가 아니에요'], '실제 참조가 둘에서 하나로 줄어도 false입니다. 수를 하나 낮추는 일과 마지막 사용자가 끝났음을 확정하는 일은 다르므로 false에서 객체를 파괴하면 안 됩니다.'), ('__rcuref_put을 아무 문맥에서 직접 부르는 것이 정상 사용법일까요?', ['아니요. 내부 helper이므로 알맞은 공개 함수를 써야 해요', '네. 모든 문맥에서 직접 호출하도록 권장해요'], '헤더는 직접 호출하지 말라고 명시합니다. 일반 put은 문맥 보호를 더하고 rcusafe 버전은 이미 안전한 조건에서 사용하도록 약속되어 있습니다.')]), 'os1399': ('장부에 사용자가 없다고 잠깐 보인 뒤에도 새 사용자가 들어올 수 있습니다. 폐점 표시를 확정하기 직전에 상태가 그대로인지 다시 확인합니다.', 'NOREF에서 DEAD로 바꾸는 마지막 비교와 실패 처리를 배웁니다.', 'NOREF를 읽고 비교하는 사이 상태가 바뀌지 않으면 DEAD·true, 새 사용자가 들어와 ONEREF면 변경 없이 false, 다른 처리자가 DEAD를 만들었어도 false라고 적으세요.', ['rcuref_put_slowpath는 내부 수를 다시 읽습니다. NOREF=0xffffffff이면 마지막 감소 뒤의 상태를 관측한 것입니다. 하지만 아직 다른 get이 참조를 얻을 수 있는 짧은 틈이 있으므로 그 관측만으로 파괴를 확정하지 않습니다.', 'atomic_try_cmpxchg_release는 실제 값이 예상한 NOREF와 같을 때만 DEAD로 바꾸려 합니다. CAS라고 부르는 비교·교환입니다. 성공하면 이 호출이 새 참조를 더 얻지 못하는 상태로 확정한 것입니다.', '비교가 실패할 수도 있습니다. 다른 get이 수를 다시 올렸거나, 다른 get과 put이 이어져 이미 DEAD를 만들었을 수 있습니다. 원문은 둘 다 가능한 상황으로 설명하며 이 호출은 false를 반환합니다.', '실패 후 성공할 때까지 반복하지 않습니다. 상태가 달라졌는데 자신이 반드시 마지막 처리자가 되려고 강제로 DEAD를 쓰면 새 참조나 이미 진행한 마지막 처리를 망가뜨릴 수 있습니다. 이 호출은 파괴 권한 없이 끝냅니다.', 'CAS가 성공하면 smp_acquire__after_ctrl_dep를 수행하고 true를 반환합니다. 성공 여부에 따른 흐름 뒤에 acquire 순서를 보충해 마지막 해제 작업이 필요한 접근보다 앞서지 않게 합니다. 이는 반환값만 계산하는 것과 다른 역할입니다.', '함수 안에는 free 호출이 없습니다. true를 받은 호출자가 제거·반납 예약 등 해당 객체의 RCU 수명 규칙을 이어 갑니다. true라고 RCU 독자 보호를 무시하고 아무 때나 메모리를 버려도 된다는 뜻은 아닙니다.'], [('마지막 NOREF→DEAD 비교가 실패하면 성공할 때까지 반복할까요?', ['네. 언제나 무한히 재시도해요', '아니요. false를 반환하고 끝내요'], '다른 사용자가 들어왔거나 다른 호출이 마지막 처리를 맡았을 수 있습니다. 이 호출에 파괴 권한을 주지 않고 끝내므로 무조건 재시도하지 않습니다.'), ('이 함수가 true를 반환하는 본문에서 객체를 직접 free할까요?', ['아니요. 호출자가 마지막 수명 처리를 이어 가도록 알려 줘요', '네. 본문이 즉시 메모리 반납 함수를 호출해요'], '본문은 상태 비교·변경과 접근 순서 보장을 수행합니다. 실제 제거와 메모리 반납은 호출자가 RCU 규칙에 맞게 진행하는 별도 단계입니다.')]), 'os1400': ('손님이 0명이 된 순간과 문에 폐점 표시를 확정한 순간은 다릅니다. 그 사이 새 손님이 들어오면 폐점을 확정하려던 쪽은 멈춰야 합니다.', 'NOREF와 DEAD 사이의 경쟁 순서를 숫자로 추적합니다.', 'A의 마지막 감소: 0→NOREF. B의 get: NOREF→0. A의 NOREF 비교 실패: false. 다른 순서로 A가 먼저 DEAD를 만들면 B의 증가 결과는 DEAD+1이고 거절된다고 두 줄을 그리세요.', ['rcuref 내부 0은 실제 참조 하나를 뜻합니다. 마지막 put이 하나 줄이면 32비트 표현이 NOREF=0xffffffff가 됩니다. 다음 단계에서 비교·교환으로 DEAD=0xe0000000을 확정하려 합니다. 두 단계 사이에는 다른 실행이 들어올 수 있습니다.', '그 사이 get이 먼저 1을 더하면 0xffffffff의 32비트 값이 0으로 돌아옵니다. 이 내부 0은 ONEREF, 즉 참조 하나입니다. get은 음수 결과가 아니므로 성공할 수 있습니다. 커널의 이 원자 카운터 동작을 보는 것입니다.', '단순한 두 호출 예시에서 A가 아직 NOREF라고 예상했는데 B의 get이 내부 0을 만들면 A의 CAS는 실패합니다. A는 false를 반환하고 객체를 파괴하지 않습니다. 새 사용 약속이 생겼음을 마지막 비교가 반영한 것입니다.', '순서가 반대라서 A가 먼저 DEAD를 확정했다면 B의 증가는 0xe0000001이 됩니다. 여전히 종료 구역이므로 get slowpath가 DEAD로 되돌리고 false를 반환합니다. DEAD에 한 번 더한다고 ONEREF로 돌아오지 않습니다.', 'NOREF와 DEAD는 그래서 같은 완료 표지가 아닙니다. NOREF는 마지막 확정을 시도하는 중의 상태이고 DEAD는 새 참조를 거절하는 상태입니다. 더 복잡한 get·put 경쟁에서는 다른 호출이 확정을 맡을 수 있으므로 각 반환과 사건 순서를 따라가야 합니다.', '이 이야기는 RCU 등으로 메모리가 아직 유효하게 보호되는 범위 안에서만 성립합니다. 실제로 free된 주소에 get을 호출해 되살리는 규칙이 아닙니다. 일반 signed 정수 계산이나 임의 포인터에 이 예시를 그대로 적용하면 안 됩니다.'], [('NOREF에서 DEAD 확정 전에 get이 먼저 증가하면 어떤 일이 가능할까요?', ['언제나 이미 종료되었다고 실패해요', '내부 0인 ONEREF로 돌아와 성공할 수 있어요'], '32비트 표현 0xffffffff에 1을 더하면 0입니다. 종료 확정 전의 이 틈에서는 참조가 다시 생길 수 있고, 뒤의 마지막 CAS는 그 변경을 확인해야 합니다.'), ('DEAD가 확정된 뒤 한 번 get하면 곧바로 일반 값 0이 될까요?', ['아니요. 종료 구역에 남아 거절돼요', '네. 한 번 증가하면 언제나 ONEREF예요'], 'DEAD는 0xe0000000이라 1을 더해도 0xe0000001입니다. 종료 구역 안에 남으므로 별도 처리가 DEAD를 복구하고 실패를 반환합니다. NOREF와 다른 값입니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_345.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
